import re

def react_agent(query, tools, max_iterations=5):
    trajectory = []
    thought = f"Thought: I need to answer: {query}"
    for i in range(max_iterations):
        trajectory.append(thought)
        if "Final Answer:" in thought:
            return {"answer": thought.split("Final Answer:")[1].strip(), "trajectory": trajectory}
        action_match = re.search(r"Action:\s*(\w+):\s*(.*)", thought)
        if action_match:
            action_name = action_match.group(1)
            action_input = action_match.group(2)
            if action_name in tools:
                observation = tools[action_name](action_input)
                thought = f"Observation: {observation}\nThought:"
                trajectory.append(thought)
            else:
                thought = f"Observation: Unknown tool {action_name}\nThought:"
        else:
            thought = f"Thought: I need to use a tool to answer this."
    return {"answer": "Could not find answer", "trajectory": trajectory}
